const TILE_GEOMETRY = {
    "Golden Penrose Rhomb": { N: 10, K: 0.381966 },
    "Ammann Beenker Octagons": { N: 8, K: 0.414213 },
    "Robinson Golden Triangles": { N: 6, K: 0.333333 },
    "Danzer Sevenfold Stars": { N: 7, K: 0.400000 },
    "Pinwheel Radical Fractures": { N: 5, K: 0.381966 },
    "Conway Biparabola Shards": { N: 12, K: 0.267949 }
};

const DIVE_TEMPO = {
    "Glacial Glide": 0.001,
    "Languid Float": 0.003,
    "Brisk Submersion": 0.008,
    "Centrifuge Plunge": 0.015,
    "Hyperbolic Abyss": 0.025,
    "Relativistic Warp": 0.040
};

const VERTEX_PROFILE = {
    "Cathedral Lead Came": { w: 4, warp: 0, alpha: 1.0 },
    "Beveled Prism Edges": { w: 2, warp: 0, alpha: 0.9 },
    "Skeletal Ribbon Insets": { w: 1, warp: 0.5, alpha: 0.85 },
    "Breathing Optical Warp": { w: 2, warp: 2.0, alpha: 0.85 },
    "Filigree Caustic Spines": { w: 1.2, warp: 1.0, alpha: 0.9 },
    "Dissolving Wire Web": { w: 1.0, warp: 3.0, alpha: 0.85 }
};

const CHROMA_LOGIC = {
    "Sainte Chapelle Ruby": ["#4a0000", "#7a0010", "#c21807", "#002a54", "#d4af37"],
    "Cobalt Nave Twilight": ["#00102a", "#002050", "#003a8c", "#4a0080", "#101010"],
    "Alchemical Emerald Glow": ["#001a00", "#003311", "#006622", "#33cc33", "#ccff00"],
    "Orientation Phase Prism": ["#ff0040", "#00ff40", "#4000ff", "#ffcc00", "#00ffff"],
    "Inflation Depth Opal": ["#ffcccc", "#ccffcc", "#ccccff", "#ffffcc", "#ffccff"],
    "Monochrome Obsidian Flare": ["#050505", "#151515", "#252525", "#404040", "#ffffff"]
};

const DRIFT_WANDER = {
    "Dead Center Orbit": { x: 0, y: 0 },
    "Gentle Precession": { x: 0.1, y: 0.05 },
    "Spiral Fibonacci Eddy": { x: 0.3, y: 0.3 },
    "Erratic Tidal Shear": { x: 0.5, y: 0.8 },
    "Vortical Edge Skim": { x: 0.8, y: 0.2 },
    "Chaotic Brownian Tremor": { x: 1.2, y: 1.5 }
};

let colorBuckets = [[], [], [], [], []];

p.setup = function() {
    p.createCanvas(800, 800);
};

p.draw = function() {
    let geomStr = p.getSynthVar('tile_geometry') || 'Golden Penrose Rhomb';
    let tempoStr = p.getSynthVar('dive_tempo') || 'Glacial Glide';
    let profileStr = p.getSynthVar('vertex_profile') || 'Cathedral Lead Came';
    let chromaStr = p.getSynthVar('chroma_logic') || 'Sainte Chapelle Ruby';
    let driftStr = p.getSynthVar('drift_wander') || 'Dead Center Orbit';

    let geom = TILE_GEOMETRY[geomStr];
    let speed = DIVE_TEMPO[tempoStr];
    let profile = VERTEX_PROFILE[profileStr];
    let colors = CHROMA_LOGIC[chromaStr];
    let drift = DRIFT_WANDER[driftStr];

    p.background('#000000');

    let time = p.frameCount;
    let cx = 800 / 2 + Math.sin(time * 0.01) * drift.x * (800 / 3);
    let cy = 800 / 2 + Math.cos(time * 0.013) * drift.y * (800 / 3);

    let zoomProgress = (time * speed) % 1.0;
    let scaleFactor = Math.pow(1 / geom.K, zoomProgress);
    let baseR = 1800 * scaleFactor;

    colorBuckets = [[], [], [], [], []];

    let currentR = baseR;
    let depth = 0;
    while (currentR > 2) {
        let outV = [];
        let inV = [];
        for (let i = 0; i < geom.N; i++) {
            let a = (i * Math.PI * 2) / geom.N;
            outV.push({ x: cx + currentR * Math.cos(a), y: cy + currentR * Math.sin(a) });
            inV.push({ x: cx + currentR * geom.K * Math.cos(a), y: cy + currentR * geom.K * Math.sin(a) });
        }

        for (let i = 0; i < geom.N; i++) {
            let next = (i + 1) % geom.N;
            let subDepth = 0;
            if (currentR > 800) subDepth = 3;
            else if (currentR > 200) subDepth = 2;
            else if (currentR > 40) subDepth = 1;

            subdivideQuad(outV[i], outV[next], inV[next], inV[i], 0, subDepth, i + depth);
        }
        currentR *= geom.K;
        depth++;
    }

    let centerPoly = [];
    for (let i = 0; i < geom.N; i++) {
        let a = (i * Math.PI * 2) / geom.N;
        centerPoly.push({ x: cx + currentR * Math.cos(a), y: cy + currentR * Math.sin(a) });
    }
    colorBuckets[depth % 5].push(centerPoly);

    let ctx = p.drawingContext;
    ctx.lineJoin = 'bevel';
    ctx.lineWidth = profile.w;
    ctx.strokeStyle = '#000000';
    if (profile.alpha < 1.0) ctx.globalAlpha = profile.alpha;

    let warpTime = time * 0.05;

    for (let i = 0; i < 5; i++) {
        if (colorBuckets[i].length === 0) continue;
        ctx.fillStyle = colors[i];
        ctx.beginPath();
        for (let poly of colorBuckets[i]) {
            if (profile.warp > 0) {
                let wx0 = poly[0].x + Math.sin(poly[0].y * 0.01 + warpTime) * profile.warp * 4;
                let wy0 = poly[0].y + Math.cos(poly[0].x * 0.01 + warpTime) * profile.warp * 4;
                ctx.moveTo(wx0, wy0);
                for (let j = 1; j < poly.length; j++) {
                    let wx = poly[j].x + Math.sin(poly[j].y * 0.01 + warpTime) * profile.warp * 4;
                    let wy = poly[j].y + Math.cos(poly[j].x * 0.01 + warpTime) * profile.warp * 4;
                    ctx.lineTo(wx, wy);
                }
                ctx.closePath();
            } else {
                ctx.moveTo(poly[0].x, poly[0].y);
                for (let j = 1; j < poly.length; j++) {
                    ctx.lineTo(poly[j].x, poly[j].y);
                }
                ctx.closePath();
            }
        }
        ctx.fill();
        if (profile.w > 0) ctx.stroke();
    }
    ctx.globalAlpha = 1.0;
};

function subdivideQuad(A, B, C, D, depth, maxDepth, colOffset) {
    let minX = Math.min(A.x, B.x, C.x, D.x);
    let maxX = Math.max(A.x, B.x, C.x, D.x);
    let minY = Math.min(A.y, B.y, C.y, D.y);
    let maxY = Math.max(A.y, B.y, C.y, D.y);

    if (maxX < -50 || minX > 850 || maxY < -50 || minY > 850) return;

    if (depth >= maxDepth || (maxX - minX < 12 && maxY - minY < 12)) {
        colorBuckets[(depth + colOffset) % 5].push([A, B, C, D]);
        return;
    }

    let E = { x: (A.x+B.x+C.x+D.x)/4, y: (A.y+B.y+C.y+D.y)/4 };
    let MAB = { x: (A.x+B.x)/2, y: (A.y+B.y)/2 };
    let MBC = { x: (B.x+C.x)/2, y: (B.y+C.y)/2 };
    let MCD = { x: (C.x+D.x)/2, y: (C.y+D.y)/2 };
    let MDA = { x: (D.x+A.x)/2, y: (D.y+A.y)/2 };

    subdivideQuad(A, MAB, E, MDA, depth+1, maxDepth, colOffset);
    subdivideQuad(MAB, B, MBC, E, depth+1, maxDepth, colOffset+1);
    subdivideQuad(E, MBC, C, MCD, depth+1, maxDepth, colOffset+2);
    subdivideQuad(MDA, E, MCD, D, depth+1, maxDepth, colOffset+3);
}
